// Customer-validation experiments and their recorded results. Results become evidence automatically, always as
// human-recorded USER_REPORTED data; nothing here is generated by AI.
import type { z } from "zod";
import { AppError } from "../../../lib/errors";
import { prisma } from "../../../lib/prisma";
import { logActivity } from "../venture-builder.repository";
import type { experimentResultSchema, experimentSchema, updateExperimentSchema } from "../venture-builder.schemas";
import type { ProjectAccess } from "../venture-builder.types";

export const listExperiments = (projectId: string) =>
  prisma.ventureExperiment.findMany({ where: { projectId }, orderBy: { createdAt: "desc" }, include: { results: { orderBy: { recordedAt: "desc" } }, assumption: { select: { id: true, statement: true } } } });

const assertAssumption = async (projectId: string, assumptionId?: string | null) => {
  if (assumptionId && !(await prisma.ventureAssumption.findFirst({ where: { id: assumptionId, projectId }, select: { id: true } }))) {
    throw AppError.badRequest("Assumption does not belong to this venture", "UNKNOWN_ASSUMPTION");
  }
};

export const createExperiment = async (access: ProjectAccess, input: z.infer<typeof experimentSchema>) => {
  await assertAssumption(access.projectId, input.assumptionId);
  if (input.startDate && input.endDate && input.endDate < input.startDate) throw AppError.badRequest("End date must be after the start date");
  const row = await prisma.ventureExperiment.create({ data: { projectId: access.projectId, ...input, assumptionId: input.assumptionId ?? null, createdById: access.userId } });
  await logActivity({ projectId: access.projectId, actorId: access.userId, action: "experiment.created", summary: `Planned experiment: ${row.hypothesis.slice(0, 120)}`, entityType: "experiment", entityId: row.id });
  return row;
};

export const updateExperiment = async (access: ProjectAccess, id: string, input: z.infer<typeof updateExperimentSchema>) => {
  const existing = await prisma.ventureExperiment.findFirst({ where: { id, projectId: access.projectId } });
  if (!existing) throw AppError.notFound("Experiment not found");
  await assertAssumption(access.projectId, input.assumptionId);
  const row = await prisma.ventureExperiment.update({ where: { id }, data: { ...input, assumptionId: input.assumptionId === undefined ? undefined : input.assumptionId } });
  if (input.status && input.status !== existing.status) {
    await logActivity({ projectId: access.projectId, actorId: access.userId, action: "experiment.status_changed", summary: `Experiment ${existing.status} → ${row.status}`, entityType: "experiment", entityId: id });
    if (input.status === "RUNNING" && existing.assumptionId) {
      await prisma.ventureAssumption.updateMany({ where: { id: existing.assumptionId, projectId: access.projectId, status: "UNTESTED" }, data: { status: "TESTING" } });
    }
  }
  return row;
};

const DIRECTION = { SUPPORTS: "SUPPORTS", CONTRADICTS: "CONTRADICTS", INCONCLUSIVE: "NEUTRAL" } as const;

export const recordResult = async (access: ProjectAccess, experimentId: string, input: z.infer<typeof experimentResultSchema>) => {
  const experiment = await prisma.ventureExperiment.findFirst({ where: { id: experimentId, projectId: access.projectId } });
  if (!experiment) throw AppError.notFound("Experiment not found");
  if (experiment.status === "CANCELLED") throw AppError.conflict("This experiment was cancelled", "EXPERIMENT_CANCELLED");
  const { completeExperiment, ...resultData } = input;

  const out = await prisma.$transaction(async (tx) => {
    const result = await tx.ventureExperimentResult.create({ data: { experimentId, ...resultData, recordedById: access.userId } });
    const evidence = await tx.ventureEvidence.create({
      data: {
        projectId: access.projectId,
        assumptionId: experiment.assumptionId,
        experimentId,
        evidenceType: "EXPERIMENT_RESULT",
        direction: DIRECTION[input.outcome],
        description: input.observation,
        verificationStatus: "USER_REPORTED",
        createdById: access.userId,
      },
    });
    await tx.ventureExperiment.update({ where: { id: experimentId }, data: { status: completeExperiment ? "COMPLETED" : experiment.status === "PLANNED" ? "RUNNING" : undefined } });
    if (experiment.assumptionId) await tx.ventureAssumption.updateMany({ where: { id: experiment.assumptionId, projectId: access.projectId, status: "UNTESTED" }, data: { status: "TESTING" } });
    return { result, evidence };
  });
  await logActivity({ projectId: access.projectId, actorId: access.userId, action: "experiment.result_recorded", summary: `Recorded ${input.outcome.toLowerCase()} result for: ${experiment.hypothesis.slice(0, 100)}`, entityType: "experiment", entityId: experimentId });
  return out;
};
